import { useCallback, useEffect, useMemo, useRef, useState, } from 'react';
import { useAppDispatch } from '06_shared/hooks/useAppDispatch';
import { useDebouncedValue } from '06_shared/hooks/useDebouncedValue';
import { deepEqual } from '06_shared/utils/deepEqueal';
import { NOTIFICATION_KEYS } from '06_shared/constants/notificationKeys';
import { notificationActions } from '05_entities/notification';
import { roundFormValue } from '../../lib/tradePreferencesForm';
// Чернетка одного блоку налаштувань: лише змінені поля поверх збереженого,
// збереження через 2 с після останньої зміни — своїм PUT. Блоки незалежні:
// у кожного своя чернетка, своя мутація й свій лоадер.
export const usePreferencesDraft = (options) => {
    const { saved, toRequest, save, isSuccess, isError, isLoading, setIsLoading, } = options;
    const dispatch = useAppDispatch();
    const [draft, setDraft] = useState({});
    const item = useMemo(() => (saved ? { ...saved, ...draft } : null), [saved, draft]);
    const itemDebounced = useDebouncedValue(item, 2000);
    // Останнє відправлене: поки після PUT перечитується GET, збережене ще
    // старе — без цього та сама чернетка пішла б удруге.
    const lastSent = useRef(null);
    const setKeyValue = useCallback((key, value) => {
        setDraft((current) => ({ ...current, [key]: roundFormValue(key, value) }));
        setIsLoading(true);
    }, [setIsLoading]);
    useEffect(() => {
        if (!isLoading || !item || !saved)
            return;
        const next = toRequest(item);
        if (deepEqual(toRequest(saved), next)) {
            setIsLoading(false); // змінили й повернули назад — зберігати нічого
            return;
        }
        // Чекаємо, поки затримка наздожене чернетку: 2 с без нових змін.
        if (!itemDebounced || !deepEqual(toRequest(itemDebounced), next))
            return;
        if (lastSent.current && deepEqual(lastSent.current, next))
            return;
        lastSent.current = next;
        save(next);
    }, [isLoading, item, itemDebounced, saved, save, setIsLoading, toRequest]);
    useEffect(() => {
        if (!isSuccess)
            return;
        setIsLoading(false);
        dispatch(notificationActions.addNotificationItem({
            type: 'Success',
            description: [NOTIFICATION_KEYS.UPDATE_TRADE_PREFERENCES_SUCCESS],
        }));
    }, [dispatch, isSuccess, setIsLoading]);
    useEffect(() => {
        if (!isError)
            return;
        lastSent.current = null; // наступна зміна відправиться знову
        dispatch(notificationActions.addNotificationItem({
            type: 'Error',
            description: [NOTIFICATION_KEYS.UPDATE_TRADE_PREFERENCES_ERROR],
        }));
    }, [dispatch, isError]);
    return { item, setKeyValue };
};
